function savedSelector(){return `<div class="field"><label for="generation-select">Saved timetable</label><select id="generation-select">${optionsHTML(state.history.map(h=>[h.id,`${h.name} · ${h.status} · ${when(h.created_at)}`]),state.generation?.id)}</select></div>`;}
function timeAfter(start,duration){const [h,m]=start.split(':').map(Number),v=h*60+m+duration;return `${String(Math.floor(v/60)).padStart(2,'0')}:${String(v%60).padStart(2,'0')}`;}
timetablePage=function(){
 const heading=pageHeading('YOUR WEEK, AT A GLANCE','Timetables','Saved division, professor, classroom, and lab timetables, with the college name on every export.','<a class="button primary" href="#generate">Generate timetable</a>');
 const g=state.generation;if(!g)return heading+empty('No timetable yet','Choose your academic scope to generate a timetable.');
 const c=g.config,m=maps(c),r=g.result,meta=g.meta||state.meta;
 const saved=`<div class="schedule-topline">${savedSelector()}<span class="save-note">${when(g.created_at)} · Data revision ${g.config_revision}</span></div>`;
 const stale=g.config_revision!==state.revision?'<div class="info-banner warning">This is a saved snapshot. Academic changes affect future generations; this timetable and its exports retain their original data and calendar.</div>':'';
 if(r.status!=='feasible')return heading+saved+stale+diagnostics(g);
 const roomView=state.view==='classroom'||state.view==='lab';
 const targetKey=roomView?'room_id':`${state.view}_id`;
 const viewLabels={group:'Division',teacher:'Professor',classroom:'Classroom',lab:'Lab'};
 const viewControls=`<div class="view-toggle" role="group" aria-label="Timetable view">${Object.entries(viewLabels).map(([view,label])=>`<button data-action="view-${view}" class="${state.view===view?'active':''}">By ${label.toLowerCase()}</button>`).join('')}</div>`;
 const scheduled=new Set(r.entries.map(e=>e.group_id));
 let groups=c.groups.filter(x=>scheduled.has(x.id)&&(!state.department||x.department_id===state.department));
 if(state.view==='group'&&!groups.length)return heading+saved+stale+empty('No scheduled divisions in this department','Choose All departments above, or generate this department.');
 if(!groups.some(x=>x.semester===Number(state.semester)))state.semester=groups[0]?.semester||3;
 const choices=state.view==='group'?groups.filter(x=>x.semester===Number(state.semester)):roomView?c.rooms.filter(x=>x.kind===state.view):c.teachers;
 if(!choices.some(x=>x.id===state.target))state.target=choices[0]?.id||'';
 const record=choices.find(x=>x.id===state.target);if(!record)return heading+saved+stale+`<section class="panel"><div class="toolbar">${viewControls}</div>${empty('No '+viewLabels[state.view].toLowerCase()+' records','This saved timetable has no records for this view.')}</section>`;
 const batchChoices=state.view==='group'?c.batches.filter(b=>b.group_id===state.target):[];
 if(!batchChoices.some(b=>b.id===state.batch))state.batch='';
 const filteredEntries=r.entries.filter(e=>e[targetKey]===state.target&&(!state.batch||!e.batch_id||e.batch_id===state.batch)),entries=state.view==='group'?filteredEntries:uniquePhysicalSessions(c,filteredEntries),title=state.view==='group'?groupName(record,c):record.name;
 const exportUrl=format=>`/api/generations/${g.id}/export/${format}?view=${state.view}&target=${encodeURIComponent(state.target)}${state.batch?'&batch='+encodeURIComponent(state.batch):''}`;
 const rows=meta.periods.map(([start,end],slot)=>({start,end,slot})).concat((meta.breaks||[]).map(b=>({...b,end:timeAfter(b.start,b.duration),pause:true}))).sort((a,b)=>a.start.localeCompare(b.start));
 const grid=rows.map(row=>{
  if(row.pause)return `<tr class="recess"><th>${row.start}–${row.end}</th><td colspan="${meta.days.length}">${esc(row.name.toUpperCase())} · ${row.duration} MINUTES</td></tr>`;
  return `<tr><th scope="row">${row.start}–${row.end}<small>PERIOD ${row.slot+1}</small></th>${meta.days.map((day,d)=>{
   const sessions=entries.filter(e=>e.day===d&&e.slot<=row.slot&&e.slot+e.duration>row.slot),block=(meta.blocked||[]).find(b=>b.day===day&&b.slot===row.slot);
   if(!sessions.length)return `<td class="empty">${block?`<small class="blocked-label">${esc(block.reason)}</small>`:freeSlotButton(d,row.slot)}</td>`;
   return `<td><div class="session-stack ${sessions.length>1?'parallel':''}">${sessions.length>1?`<div class="parallel-label">${sessions.some(e=>combinedOption(c,e))?'Combined A+B elective options':'Separate batch sessions'}</div>`:''}`+sessions.map(e=>{const s=m.subjects[e.subject_id],t=m.teachers[e.teacher_id],group=m.groups[e.group_id];return `<div class="lesson ${e.kind!=='lecture'?'lab':''} ${s.elective||combinedOption(c,e)?'elective':''}">${e.batch_id?`<div class="batch-label">Batch ${esc(m.batches[e.batch_id].name)}</div>`:''}<div class="lesson-code">${esc(s.code)}<span>${e.kind==='lecture'?(combinedOption(c,e)?'A+B ELECTIVE':s.elective?'ELECTIVE':'LEC'):e.kind.toUpperCase()}</span></div><strong>${esc(s.name)}</strong><small>${esc(state.view==='group'?t?.name||'':groupName(group,c))}</small>${roomView?`<small>${esc(t?.name||'')}</small>`:''}<small>${esc(m.rooms[e.room_id]?.name||'')}${e.batch_id?' · '+esc(m.batches[e.batch_id].name):''}${e.duration>1?` · ${row.slot===e.slot?'Starts':'Continues'} ${e.duration*meta.period_minutes/60}h session`:''}</small></div>`;}).join('')+'</div>'+freeSlotButton(d,row.slot)+'</td>';
  }).join('')}</tr>`;
 }).join('');
 const remaining=r.scope?.remaining_group_ids||[];
 const rq=r.summary.classroom_optimization;const optionNote=r.scheduling_options?`<div class="info-banner">Generation settings: ${esc(r.scheduling_options.start)} start · Practical sessions ${r.scheduling_options.practical_hours} hour(s) (source data: ${r.scheduling_options.source_practical_hours} hours). ${r.scheduling_options.classroom_practical_codes?.length?'This saved version used classroom practicals. Generate a new timetable to apply laboratory-only allocation.':''} Major Project: independent student time; no teacher/room booking.</div>`:'';const roomNote=(r.summary.parallel_batches?`<div class="info-banner">Batch alignment: ${r.summary.parallel_batches.partial_periods} periods with some batches free. ${esc(r.summary.parallel_batches.note)}</div>`:'')+(c.settings.combined_elective_students?.IS?'<div class="info-banner">Combined A+B electives: IS 60 students / STQA 60 students, at the same times in different classrooms.</div>':'')+optionNote+(rq&&rq.preferred_periods>1?`<div class="info-banner ${rq.early_changes?'warning':'success'}">Classroom preference: ${rq.preferred_periods} consecutive lecture periods · ${rq.classroom_changes} changes · ${rq.early_changes} before the required minimum. ${rq.optimal?'Best room allocation proven for these fixed session times.':'Further improvement may be possible.'}</div>`:'');
 return heading+saved+stale+roomNote+`<div class="info-banner">${scheduled.size} scheduled divisions · ${remaining.length} remaining · ${r.scope?.locked_sessions||0} sessions preserved from the base plan.${remaining.length?`<details><summary>Remaining divisions</summary>${remaining.map(id=>esc(groupName(m.groups[id],c))).join('<br>')}</details>`:''}</div><section class="panel"><div class="toolbar">${viewControls}${state.view==='group'?`<div class="field"><label for="semester-select">Academic year</label><select id="semester-select">${optionsHTML([...new Set(groups.map(x=>x.semester))].sort().map(s=>[s,`${years[s]} · Sem ${s}`]),state.semester)}</select></div>`:''}<div class="field"><label for="target-select">${viewLabels[state.view]}</label><select id="target-select">${optionsHTML(choices.map(x=>[x.id,state.view==='group'?`${departmentOf(x.department_id,c)?.code} · Division ${x.division}`:x.name]),state.target)}</select></div>${batchChoices.length?`<div class="field"><label for="batch-select">Practical batch</label><select id="batch-select">${optionsHTML([['','All batches'],...batchChoices.map(b=>[b.id,b.name])],state.batch)}</select></div>`:''}<div class="spacer"></div><div class="button-row"><a class="button small" href="${exportUrl('pdf')}">PDF</a><a class="button small" href="${exportUrl('xlsx')}">Excel</a></div></div><div class="timetable-header"><h2 class="college-full">${esc(meta.college||state.meta.college)}</h2><p>${meta.days.join(' · ')}</p><div class="timetable-label">${esc(title)}</div><p>${entries.reduce((n,e)=>n+e.duration*meta.period_minutes/60,0)} ${state.batch?'student teaching hours':'contact hours (includes separate batches)'}${roomView?' · Blank cells show the room is free':state.view==='teacher'?' · Blank cells show no assigned teaching':''}</p></div><div class="timetable-wrap"><table class="timetable"><thead><tr><th>Time</th>${meta.days.map(d=>`<th>${d}</th>`).join('')}</tr></thead><tbody>${grid}</tbody></table></div><div class="legend">Purple: lectures · Green: labs/projects · Orange: electives. Batch sessions are labelled individually.</div></section><div class="button-row section-spacer"><a class="button" href="/api/generations/${g.id}/export/pdf">All divisions · PDF</a><a class="button" href="/api/generations/${g.id}/export/xlsx">All divisions · Excel</a><a class="button" href="/api/generations/${g.id}/export/xlsx?view=teacher">All professors · Excel</a><a class="button" href="/api/generations/${g.id}/export/xlsx?view=classroom">All classrooms · Excel</a><a class="button" href="/api/generations/${g.id}/export/xlsx?view=lab">All labs · Excel</a><a class="button" href="#analytics">Inspect timetable quality</a></div>`+diagnostics(g);
};
function workloadPage(){
 const teachers=filteredRecords('teachers'),hours=t=>state.config.offerings.filter(o=>o.teacher_id===t.id).reduce((n,o)=>n+teachingHours(o),0);
 return pageHeading('FACULTY & WORKLOAD','A fair teaching week.','Daily limits, weekly limits, availability, and laboratory eligibility are enforced together.','<a class="button primary" href="#teachers">Faculty directory</a>')+`<div class="stats-grid">${metric('Faculty',teachers.length)}${metric('Assigned teaching hours',teachers.reduce((n,t)=>n+hours(t),0))}${metric('Over weekly cap',teachers.filter(t=>hours(t)>t.max_hours).length)}</div><section class="panel">${table(['Faculty','Assigned / weekly limit','Daily limit','Availability',''],teachers.map(t=>cells([`<strong>${esc(t?.name||'')}</strong><small>${esc(t.email)}</small>`,tag(`${hours(t)} / ${t.max_hours} hours`,hours(t)>t.max_hours?'orange':'green'),`${t.max_daily_slots} periods`,`${t.arrival}–${t.departure}`,`<button class="button small" data-action="edit-faculty" data-id="${esc(t.id)}">Edit limits</button>`])))}</section><p class="inline-help">Assigned hours include all departments. Daily distribution is measured in the saved timetable’s Analytics view.</p>`;
}
function breakRow(b={name:'Break',start:'13:00',duration:45}){return `<div class="calendar-row break-row"><label>Name<input class="break-name" value="${esc(b.name)}" required maxlength="40"></label><label>Start<input class="break-start" type="time" value="${b.start}" required></label><label>Minutes<input class="break-duration" type="number" value="${b.duration}" min="5" max="120" required></label><button class="button small" data-action="remove-calendar-row">Remove</button></div>`;}
function blockRow(b={day:'Monday',slot:0,reason:'College activity'}){return `<div class="calendar-row block-row"><label>Day<select class="block-day">${optionsHTML(['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map(d=>[d,d]),b.day)}</select></label><label>Period number<input class="block-slot" type="number" min="1" max="16" value="${b.slot+1}" required></label><label>Reason<input class="block-reason" value="${esc(b.reason)}" required maxlength="60"></label><button class="button small" data-action="remove-calendar-row">Remove</button></div>`;}
function timingsPage(){const s=state.config.settings;return pageHeading('COLLEGE CALENDAR','Make time for every session.','Changes apply to future generations. Saved versions retain their original calendar.')+`<form id="timings-form"><section class="panel"><div class="panel-header"><h2>Operating hours & session lengths</h2></div><div class="panel-body"><div class="form-grid">${inputField('start','College start',s.start,'time','required')}${inputField('end','College end',s.end,'time','required')}${inputField('period_minutes','Minutes per teaching period',s.period_minutes,'number','required min="30" max="90"')}${inputField('lecture_slots','Consecutive periods per lecture',s.lecture_slots,'number','required min="1" max="2"')}${inputField('lab_slots','Consecutive periods per laboratory',s.lab_slots,'number','required min="1" max="4"')}${inputField('project_slots','Consecutive periods per project',s.project_slots,'number','required min="1" max="6"')}</div><label class="checkbox-field"><input type="checkbox" name="spread_lectures" ${s.spread_lectures?'checked':''}> Spread each subject’s weekly lectures across different days</label><h3>Working days</h3><div class="checkbox-row">${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map(d=>`<label><input type="checkbox" name="days" value="${d}" ${s.days.includes(d)?'checked':''}> ${d}</label>`).join('')}</div><p class="inline-help">Every teaching day starts at the first available period. A session cannot cross a break or blocked period. End time and breaks must fit complete periods.</p></div></section><section class="panel section-spacer"><div class="panel-header"><h2>Lunch & breaks</h2>${btn('Add break','add-break','plus')}</div><div class="panel-body" id="break-rows">${s.breaks.map(breakRow).join('')}</div></section><section class="panel section-spacer"><div class="panel-header"><h2>Blocked college activities</h2>${btn('Add blocked period','add-block','plus')}</div><div class="panel-body" id="block-rows">${s.blocked.map(blockRow).join('')}</div></section><div class="form-error" id="calendar-error" role="alert"></div><div class="button-row section-spacer">${btn('Preview periods','preview-calendar','clock')}<button class="button primary" type="submit">Save college timings</button></div><div id="calendar-preview"></div></form>`;}
function readCalendar(){const f=$('#timings-form'),v=Object.fromEntries(new FormData(f));for(const k of ['period_minutes','lecture_slots','lab_slots','project_slots'])v[k]=Number(v[k]);v.spread_lectures=f.elements.spread_lectures.checked;v.days=[...f.querySelectorAll('[name="days"]:checked')].map(x=>x.value);v.breaks=[...f.querySelectorAll('.break-row')].map(r=>({name:r.querySelector('.break-name').value,start:r.querySelector('.break-start').value,duration:Number(r.querySelector('.break-duration').value)}));v.blocked=[...f.querySelectorAll('.block-row')].map(r=>({day:r.querySelector('.block-day').value,slot:Number(r.querySelector('.block-slot').value)-1,reason:r.querySelector('.block-reason').value}));return v;}
function displayCalendar(meta){$('#calendar-preview').innerHTML=`<div class="info-banner success section-spacer">${meta.periods.length} teaching periods per day · ${meta.days.length} working days</div><div class="period-preview">${meta.periods.map(([a,b],i)=>`<div><strong>P${i+1}</strong><small>${a}–${b}</small></div>`).join('')}</div>`;}
importPage=function(){return pageHeading('IMPORT & BACKUP','Bring your semester into focus.','Import CSV, Excel, or a full JSON backup. Preview before replacing academic data.',`<a class="button" href="/api/config.json">Back up current data</a>`)+`<div class="import-grid"><section class="panel"><div class="panel-header"><h2>Import academic data</h2>${tag('CSV · XLSX · JSON','purple')}</div><div class="dropzone" id="dropzone"><div class="upload-icon">${icon('upload')}</div><h3>Drop your academic data here</h3><p>Up to 1 MB · Use the supplied templates</p><span class="button primary">Choose data file</span><input type="file" id="csv-file" accept=".csv,.xlsx,.json" aria-label="Choose academic data file"></div><div id="import-result">${state.preview?importPreview():''}</div><div class="mini-note">Imports replace current academic data, including calendar settings in the new templates. Saved timetables remain available. Excel and JSON preserve unassigned records and all identifiers.</div></section><div><section class="panel next-card"><div class="eyebrow">SUPPLIED OFFICIAL DATA</div><h3>College curriculum.<br>Original CSV preserved.</h3><p>34 subjects · 24 named faculty · 8 divisions<br>7 classrooms · 6 labs · 24 batches<br>9 tutorial assignments in room 710<br>Semesters 3, 5: A/B/C; semester 7: A/B</p><p>Two-hour practical requirements exceed the six labs’ five-day capacity. Generation reports insufficient capacity without shortening practicals. Major Project uses reserved student time with no teacher or room. Labs use laboratories only; changing room types or combining batches is not a capacity workaround.</p>${btn('Preview supplied college data','sample','arrow','primary')}<div class="button-row section-spacer"><a class="button small" href="/api/demo/csv">CSV</a><a class="button small" href="/api/demo/xlsx">Excel</a><a class="button small" href="/api/demo/json">JSON</a></div></section><section class="panel next-card section-spacer"><h3>Editable templates</h3><p>CSV uses one row per teaching assignment. Room pools and calendar appear as JSON in the first row. Excel separates departments, subjects, faculty, rooms, divisions, batches, elective sets, assignments, and settings into sheets.</p><div class="button-row"><a class="button small" href="/api/config.xlsx">Export current Excel</a><a class="button small" href="/api/config.csv">Export current CSV</a><a class="button small" href="/api/sample.csv">Original supplied CSV</a></div></section></div></div>`;};
importPreview=function(){const p=state.preview;return `<div class="import-preview"><h3>${esc(p.filename)}</h3><div class="preview-counts">${Object.entries(p.counts).map(([k,v])=>tag(`${v} ${categories[k]||k}`,'purple')).join('')}</div>${p.issues.length?`<ul class="diagnostic-list">${p.issues.map(i=>`<li><strong>${esc(i.problem)}</strong><br>${esc(i.suggestion)}</li>`).join('')}</ul>`:'<p class="inline-help">Structure and basic capacity checks passed. Generate to check the full timetable.</p>'}<p class="inline-help">This replaces current academic data and calendar settings. Download a backup first if needed.</p><div class="button-row">${btn('Replace academic data','apply-import','check','primary')}<a class="button small" href="/api/config.json">Full backup</a></div></div>`;};
previewFile=async function(file){if(file.size>1_000_000){toast('Choose a data file smaller than 1 MB.');return;}state.preview=null;const revision=state.revision;if($('#import-result'))$('#import-result').innerHTML='<p class="panel-body">Validating academic data…</p>';try{const form=new FormData();form.append('file',file);const result=await api('/api/import/preview',{method:'POST',body:form});state.preview={...result,filename:file.name,revision};if(state.page==='import')$('#import-result').innerHTML=importPreview();}catch(error){if($('#import-result'))$('#import-result').innerHTML=`<p class="form-error panel-body" role="alert">${esc(error.message)}</p>`;else toast(error.message);}};
function historyPage(){return pageHeading('VERSION HISTORY','Every generation, preserved.','Each saved version includes its own academic data, constraints, and calendar.')+`<section class="panel">${table(['Timetable','Created','Data revision','Status',''],state.history.map(h=>cells([esc(h.name),when(h.created_at),h.config_revision,statusTag(h.status),`<button class="button small" data-action="open-generation" data-id="${h.id}">Open version</button>`])))}</section>`;}
function analyticsPage(){return pageHeading('ANALYTICS & CONFLICT INSPECTOR','See what the timetable solved.','Measured from the selected saved timetable, including its original room pool and calendar.')+(state.generation?`<div class="schedule-topline">${savedSelector()}</div><div id="analytics-content"><p>Calculating timetable quality…</p></div>`:empty('Generate a timetable first','Analytics are calculated from saved sessions.'));}
async function loadAnalytics(){const g=state.generation;if(!g)return;try{const a=state.analyticsCache[g.id]||await api(`/api/generations/${g.id}/analytics`);state.analyticsCache[g.id]=a;if(state.page!=='analytics'||state.generation?.id!==g.id)return;const node=$('#analytics-content');if(!a.available){node.innerHTML=diagnostics(g);return;}node.innerHTML=`<div class="stats-grid">${metric('Audited health',a.health_score+'/100')}${metric('Student quality',a.student_quality+'/100','Teaching periods / occupied span')}${metric('Room usage',a.room_utilization+'%','All available room-periods')}${metric('Hard conflicts',a.hard_conflicts)}</div><div class="info-banner ${a.hard_conflicts?'warning':'success'}">${a.internal_gaps} internal gaps · ${a.idle_minutes} idle student-unit minutes · ${a.compact_days}/${a.active_student_days} compact student days</div>${a.violations.length?`<section class="panel panel-body"><h2>Conflict inspector</h2><ul>${a.violations.map(v=>`<li>${esc(v)}</li>`).join('')}</ul></section>`:''}<section class="panel section-spacer"><div class="panel-header"><h2>Student daily timetable quality</h2></div>${table(['Division / batch','Day','Start–end','Periods','Gaps'],a.student_days.map(r=>cells([esc(`${r.department} · Sem ${r.semester} · Div ${r.division} · ${r.batch}`),r.day,`${r.start}–${r.end}`,r.periods,tag(r.gaps,r.gaps?'orange':'green')])))}</section><section class="panel section-spacer"><div class="panel-header"><h2>Faculty teaching hours</h2></div>${table(['Teacher','Hours / weekly cap','Daily periods','Daily cap'],a.teachers.map(t=>cells([esc(t?.name||''),`${t.hours} / ${t.weekly_limit}`,t.daily.join(' / '),t.daily_limit])))}</section><section class="panel section-spacer"><div class="panel-header"><h2>Shared room utilization</h2></div>${table(['Room','Type / seats','Occupied periods','Available periods','Usage'],a.rooms.map(r=>cells([esc(r.name),`${r.kind} / ${r.capacity}`,r.used_periods,r.available_periods,r.utilization+'%'])))}</section><p class="inline-help">${esc(a.method)}</p>`;}catch(e){if($('#analytics-content'))$('#analytics-content').textContent=e.message;}}
function performancePage(){return pageHeading('PERFORMANCE & DIAGNOSTICS','A measured view of the server.','Actual generation runs, request latency, uptime, and process memory.',btn('Refresh','refresh-performance','refresh'))+'<div id="performance-content"><p>Loading measurements…</p></div>';}
async function loadPerformance(){try{const p=await api('/api/performance');if(state.page!=='performance')return;const val=(v,suffix='')=>v===null?'No samples':esc(v)+suffix;$('#performance-content').innerHTML=`<div class="stats-grid">${metric('Average generation',val(p.average_generation_seconds,'s'))}${metric('Success rate',val(p.success_rate,'%'))}${metric('Average API latency',val(p.average_api_ms,' ms'))}${metric('Peak process memory',val(p.peak_memory_mb,' MB'))}</div><section class="panel panel-body"><p>Python ${esc(p.python)} · ${esc(p.platform)} · Uptime ${p.uptime_seconds}s · ${p.active_generation?'Generation in progress':'Ready'}</p><p>95th percentile API latency: ${val(p.p95_api_ms,' ms')} · ${p.request_samples} request samples</p><p>Fastest generation: ${val(p.fastest_seconds,'s')} · Slowest: ${val(p.slowest_seconds,'s')}</p><p class="inline-help">${esc(p.measurement_note)}</p></section><section class="panel section-spacer"><div class="panel-header"><h2>Recent generation runs</h2></div>${table(['Run','Status','Duration','Sessions',''],p.runs.map(r=>cells([esc(r.name),statusTag(r.status),r.duration+'s',r.sessions,`<button class="button small" data-action="open-generation" data-id="${r.id}">View report</button>`])))}</section>`;}catch(e){if($('#performance-content'))$('#performance-content').textContent=e.message;}}

action=async function(name,node){
 if(name==='tab'){state.tab=node.dataset.tab;state.search='';location.hash=({offerings:'setup',elective_sets:'electives'}[state.tab]||state.tab);render();return;}
 if(name==='generate-scope'){generationModal();return;}
 if(name==='generate-division'){generationModal([node.dataset.id]);return;}
 if(name==='subject-assignments'){const subject=state.config.subjects.find(s=>s.id===node.dataset.id);closeModal();state.tab='offerings';state.search=subject?.code||'';location.hash='setup';render();return;}
 if(name==='add-batch'){state.tab='batches';editModal(null,{group_id:node.dataset.id});return;}
 if(name==='edit-faculty'){state.tab='teachers';editModal(node.dataset.id);return;}
 if(name==='sample'){const r=await fetch('/api/demo/json');if(!r.ok)throw Error('Cannot load IT reference data.');await previewFile(new File([await r.blob()],'it_official_data.json'));return;}
 if(name==='apply-import'){if(!state.preview)return;node.disabled=true;try{await saveConfig(state.preview.configuration,state.preview.revision);state.preview=null;state.department='';state.tab='offerings';state.search='';location.hash='setup';render();toast('Academic data imported. Saved timetable versions remain available.');}finally{node.disabled=false;}return;}
 if(name==='open-generation'){state.generation=await api('/api/generations/'+node.dataset.id);state.target='';location.hash='timetables';render();return;}
 if(name==='add-break'){$('#break-rows').insertAdjacentHTML('beforeend',breakRow());return;}
 if(name==='add-block'){$('#block-rows').insertAdjacentHTML('beforeend',blockRow());return;}
 if(name==='remove-calendar-row'){node.closest('.calendar-row').remove();return;}
 if(name==='preview-calendar'){try{const meta=await api('/api/calendar/preview',jsonOptions('POST',readCalendar()));$('#calendar-error').textContent='';displayCalendar(meta);}catch(e){$('#calendar-error').textContent=e.message;}return;}
 if(name==='refresh-performance'){await loadPerformance();return;}
 return originalAction(name,node);
};
document.addEventListener('change',event=>{if(event.target.id==='department-switch'){state.department=event.target.value;state.target='';state.search='';state.generationSemester='';render();}if(event.target.id==='batch-select'){state.batch=event.target.value;render();}if(event.target.id==='scope-semester'){state.generationSemester=event.target.value;render();}});
document.addEventListener('submit',async event=>{if(event.target.id!=='timings-form')return;event.preventDefault();const button=event.target.querySelector('[type="submit"]');button.disabled=true;try{const next=structuredClone(state.config);next.settings=readCalendar();await saveConfig(next);render();toast('College timings saved for future generations.');}catch(e){$('#calendar-error').textContent=e.message;}finally{button.disabled=false;}});
if(state.config)render();
